<?= $this->extend('frontend/layouts/main') ?><?= $this->section('head') ?><?php $schema=['@context'=>'https://schema.org','@type'=>'Product','name'=>$package['name'],'description'=>strip_tags((string)($package['short_description']?:$package['description'])),'image'=>store_image($package['main_image']??null),'offers'=>['@type'=>'Offer','priceCurrency'=>'BDT','price'=>(float)$package['package_price'],'availability'=>$package['available']>0?'https://schema.org/InStock':'https://schema.org/OutOfStock','url'=>current_url()]]; ?><script type="application/ld+json"><?= json_encode($schema,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG) ?></script><?= $this->endSection() ?><?= $this->section('content') ?><div class="container py-3"><?= view('frontend/partials/breadcrumb',['items'=>[['label'=>'গার্ডেনিং প্যাক','url'=>url_to('catalog.packages')],['label'=>$package['name']]]]) ?></div><section class="container package-detail"><div class="row g-4 g-xl-5"><div class="col-lg-6"><div class="gallery-main package-main"><img src="<?= store_image($package['main_image']??null) ?>" width="720" height="600" alt="<?= esc($package['name'],'attr') ?>"></div></div><div class="col-lg-6"><span class="eyebrow">গার্ডেনিং প্যাক</span><h1><?= esc($package['name']) ?></h1><p class="lead-copy"><?= esc($package['short_description']) ?></p><div class="package-detail-pricing"><div><small>নিয়মিত মূল্য</small><del><?= format_bdt($package['regular_total']) ?></del></div><div><small>প্যাক মূল্য</small><strong><?= format_bdt($package['package_price']) ?></strong></div><?php if($package['savings']>0): ?><span>সাশ্রয় <?= format_bdt($package['savings']) ?></span><?php endif ?></div><p class="detail-stock <?= $package['available']>0?'in':'out' ?>"><?= $package['available']>0?'✓ স্টক আছে':'✕ স্টক শেষ' ?></p><form method="post" action="<?= url_to('cart.add') ?>"><?= csrf_field() ?><input type="hidden" name="item_type" value="package"><input type="hidden" name="package_id" value="<?= (int)$package['id'] ?>"><input type="hidden" name="quantity" value="1"><div class="purchase-placeholder"><button class="btn btn-primary btn-lg" <?= $package['available']<=0?'disabled':'' ?>>কার্টে যোগ করুন</button><button class="btn btn-earth btn-lg" formaction="<?= url_to('buy.now') ?>" <?= $package['available']<=0?'disabled':'' ?>>এখনই কিনুন</button></div></form></div></div></section><section class="container section"><div class="row g-4"><div class="col-lg-7"><h2>এই প্যাকে যা থাকছে</h2><div class="package-contents"><?php foreach($items as $item): ?><a href="<?= url_to('catalog.product',$item['product_slug']) ?>"><img src="<?= store_image($item['main_image']??null) ?>" width="72" height="72" alt=""><span><strong><?= esc($item['product_name']) ?></strong><?php if($item['variant_name']): ?><small><?= esc($item['variant_name']) ?></small><?php endif ?></span><b>× <?= (int)$item['quantity'] ?></b></a><?php endforeach ?></div></div><div class="col-lg-5"><div class="description-card"><h2>প্যাকের বিস্তারিত</h2><p><?= nl2br(esc($package['description']?:$package['short_description']?:'বিস্তারিত তথ্য শীঘ্রই যোগ করা হবে।')) ?></p></div></div></div></section><?= $this->endSection() ?>
